  for (let i = 0; i < TOD_KEYS.length - 1; i++) {
    if (p >= TOD_KEYS[i].p && p <= TOD_KEYS[i + 1].p) { a = TOD_KEYS[i]; b = TOD_KEYS[i + 1]; break; }
  }
  const f = (p - a.p) / Math.max(1e-6, b.p - a.p);
